addTerms([
 {id:"composition",t:"Composition",la:"compositio",d:"De Deo Uno",b:"Being made up of distinct principles or parts.",p:"Any union of really distinct principles in one being: quantitative parts, matter and form, nature and suppositum, essence and existence, genus and difference, substance and accident (ST I q.3 a.7). Every composite is posterior to its components and needs a cause to unite them.",ex:"A man is composed of body and soul, of essence and existence, of substance and accidents.",where:"ST I q.3 a.7",ccc:"",conf:"Physical mixture only; metaphysical composition includes principles that are not things on their own, such as essence and esse.",rel:["simplicity","essence","esse"],lesson:"t3l2",alias:["composition","composite","composed"]},
 {id:"suppositum",t:"Suppositum",la:"suppositum",d:"Metaphysics",b:"The concrete individual that has a nature and exists: this man, this horse.",p:"The complete subsisting individual of a nature. In material things the suppositum includes individual matter and accidents and so differs from the nature (humanity); in God nature and suppositum are identical (ST I q.3 a.3).",ex:"Socrates is a suppositum; humanity is the nature he has.",where:"ST I q.3 a.3; III q.2 a.2",ccc:"",conf:"The nature itself; Socrates is not humanity, he has it.",rel:["essence","person"],lesson:"t3l2",alias:["suppositum","supposita","hypostasis"]},
 {id:"perfection",t:"Perfection (divine)",la:"perfectio",d:"De Deo Uno",b:"Lacking nothing that belongs to a thing's full actuality; in God, having every excellence without limit.",p:"Perfect means \"not wanting in actuality\" (ST I q.4 a.1 ad 1). God is universally perfect because every perfection of an effect pre-exists in its first cause in a more eminent way (q.4 a.2).",ex:"Wisdom in Solomon is a received, limited share of what God is without limit.",where:"ST I q.4",ccc:"41, 213",conf:"Moral flawlessness only; metaphysical perfection is fullness of act.",rel:["actus-purus","analogy"],lesson:"t3l3",alias:["perfection","perfections","divine perfection","perfect"]},
 {id:"eminence",t:"Eminence (way of)",la:"via eminentiae",d:"Natural theology",b:"Saying that a perfection found in creatures exists in God in a higher, unlimited way.",p:"The third of the three ways of naming God: a pure perfection is affirmed of God while its creaturely mode is denied and its excess affirmed (ST I q.12 a.12; q.13 a.3).",ex:"God is not wise as Solomon is wise; he is Wisdom itself.",where:"ST I q.12 a.12; q.4 a.2",ccc:"43",conf:"Simple magnification (\"very, very wise\"), which keeps the creaturely mode.",rel:["analogy","perfection"],lesson:"t3l3",alias:["eminence","eminently","via eminentiae"]},
 {id:"transcendentals",t:"Transcendentals",la:"transcendentalia",d:"Metaphysics",b:"Properties found wherever being is: one, true, good (and, for many Thomists, beautiful).",p:"Notions that go beyond (transcend) every category because they are convertible with being itself: thing, one, something, true, good (De veritate q.1 a.1). They add nothing real to being, only a relation of reason or a negation (ST I q.5 a.1; q.11 a.1; q.16 a.3).",ex:"Every being, as being, is good: it has some act and so is desirable.",where:"De ver. q.1 a.1; ST I qq.5, 11, 16",ccc:"41",conf:"Kantian \"transcendental\" (conditions of possible experience).",rel:["esse","perfection"],lesson:"t3l3",alias:["transcendental","transcendentals","convertible with being"]},
 {id:"good-ratio",t:"Good",la:"bonum",d:"Metaphysics",b:"What is desirable because it is perfect, that is, actual.",p:"\"Goodness is what all desire\" (Aristotle, cited ST I q.5 a.1). Being and goodness are really the same and differ in idea; goodness adds desirability and has the aspect of a final cause (q.5 aa.1, 4).",ex:"Health is good because it is the full act of a living body.",where:"ST I qq.5–6",ccc:"",conf:"Merely what is pleasant or what I happen to want.",rel:["transcendentals","final-cause"],lesson:"t3l3",alias:["goodness","the good"]},
 {id:"infinity-div",t:"Divine infinity",la:"infinitas",d:"De Deo Uno",b:"God's being is unlimited because it is not received into any limiting essence.",p:"Infinity of form, not of matter: a form or act is limited by the potency that receives it; God's esse is not received in anything, so he is infinite and perfect (ST I q.7 a.1).",ex:"A cup holds only as much water as its size allows; God's being is not \"in\" any cup.",where:"ST I q.7",ccc:"",conf:"Infinite size, number or extension (material infinity), which is imperfection.",rel:["esse","perfection","participation"],lesson:"t3l4",alias:["infinite","infinity","divine infinity"]},
 {id:"omnipresence",t:"Omnipresence",la:"ubiquitas",d:"De Deo Uno",b:"God is present in every thing and every place as the cause of its being.",p:"God is in all things \"not, indeed, as part of their essence, nor as an accident, but as an agent is present to that upon which it works\" (ST I q.8 a.1); in all things by essence, presence and power (a.3); and in the just in a special way, as known and loved (a.3).",ex:"\"Do not I fill heaven and earth, saith the Lord?\" (Jer 23:24).",where:"ST I q.8",ccc:"300",conf:"Pantheism (God is everything) or God spread out in space like a gas.",rel:["conservation","mission"],lesson:"t3l4",alias:["omnipresence","omnipresent","everywhere"]},
 {id:"immutability",t:"Immutability",la:"immutabilitas",d:"De Deo Uno",b:"God cannot change, because he lacks nothing he could gain.",p:"God is altogether immutable because he is pure act, wholly simple, and infinite (ST I q.9 a.1). Changes ascribed to him in Scripture are metaphors for changes in creatures' relation to him (a.1 ad 3).",ex:"The sun does not move when you step out of the shade; you do.",where:"ST I q.9",ccc:"212",conf:"Inertness or indifference; God is supremely living and active.",rel:["actus-purus","eternity"],lesson:"t3l5",alias:["immutable","immutability","unchangeable","changeless"]},
 {id:"eternity",t:"Eternity",la:"aeternitas",d:"De Deo Uno",b:"God's life possessed all at once, without beginning, end or succession.",p:"Boethius: \"the simultaneously-whole and perfect possession of interminable life\" (De consolatione V; ST I q.10 a.1). Eternity follows immutability as time follows motion (q.10 a.2).",ex:"A life with no 'not yet' and no 'no longer'.",where:"ST I q.10",ccc:"",conf:"Endless time (sempiternity), which still has succession.",rel:["immutability","aeviternity"],lesson:"t3l5",alias:["eternity","eternal","nunc stans"]},
 {id:"aeviternity",t:"Aeviternity (aevum)",la:"aevum",d:"De Deo Uno",b:"The duration proper to angels and the blessed: unchanging being, with change in their acts.",p:"The mean between eternity and time: aeviternal things have unchangeable being but can change in their operations (ST I q.10 a.5).",ex:"An angel's existence does not wear out, but his thoughts follow one another.",where:"ST I q.10 a.5",ccc:"",conf:"Eternity, which excludes all succession.",rel:["eternity","angel"],lesson:"t3l5",alias:["aeviternity","aevum","aeviternal"]},
 {id:"one-trans",t:"One (transcendental)",la:"unum",d:"Metaphysics",b:"A being as undivided in itself.",p:"\"One\" adds no reality to being, only the negation of division: \"one means undivided being\" (ST I q.11 a.1). Distinct from the one that begins number.",ex:"A dog cut in half is no longer one dog, and no longer a dog.",where:"ST I q.11",ccc:"",conf:"Numerical one (the first number), which belongs to quantity.",rel:["transcendentals","simplicity"],lesson:"t3l5",alias:["undivided being","unity of God"]}
]);

mkLessons("t3",[
// ===================== L2 SIMPLICITY =====================
{id:"t3l2",ord:2,code:"T3 · Lesson 2",title:"God is simple: no parts of any kind (ST I q.3)",
 outcomes:["Explain why, after proving that God exists, Thomas proceeds by saying what God is not (the way of negation).","Give the arguments that God is neither a body nor composed of matter and form (a.1–2).","Show why God is his own essence and why his essence is his existence (a.3–4), drawing on F4.","Explain why God is in no genus and has no accidents (a.5–6), drawing on the categories.","State why God is altogether simple and does not enter into composition with anything (a.7–8), and name the errors refuted."],
 prereq:["actus-purus","essence","esse","composition","suppositum","simplicity"],
 recall:[
  ["t3","What did the First Way conclude about the first mover?","That there is a first mover moved by no other: something wholly in act, with no potency still to be actualised. Everyone understands this to be God (ST I q.2 a.3). Lesson 2 takes that \"wholly in act\" and asks what it excludes."],
  ["f4","In creatures, how are essence and existence related?","They are really distinct: what a thing is (essence) does not include that it is (esse). Essence stands to esse as potency to act and limits it (De ente c.4)."],
  ["f6","Name the three ways of knowing God from creatures.","Causality (God causes all things), negation or remotion (we deny creaturely limits of him), and eminence (perfections are in him in a higher way) (ST I q.12 a.12)."],
  ["f4","What are substance and accident?","Substance exists in itself; an accident exists in another (in a substance). There are nine kinds of accident: quantity, quality, relation, action, passion, place, time, position, possession."]],
 reading:{primary:[["ST I q.3 aa.1–8 (the simplicity of God)",NA("1003.htm")],["Thomas, De ente et essentia, ch. 4–5 (God's essence is his esse)",'https://isidore.co/aquinas/DeEnte&Essentia.htm'],["Catechism 202, 212–213 (I AM WHO AM)",'https://www.vatican.va/archive/ENG0015/__P17.HTM']],
  secondary:["Dolezal, J.E. (2011) God without Parts: Divine Simplicity and the Metaphysics of God's Absoluteness. Eugene, OR: Pickwick.","Stump, E. and Kretzmann, N. (1985) 'Absolute simplicity', Faith and Philosophy, 2(4), pp. 353–382. doi:10.5840/faithphil19852443.","Plantinga, A. (1980) Does God Have a Nature? Milwaukee: Marquette University Press (the main modern objection).","Te Velde, R. (2006) Aquinas on God: The 'Divine Science' of the Summa Theologiae. Aldershot: Ashgate, ch. 3.","Feser, E. (2017) Five Proofs of the Existence of God. San Francisco: Ignatius, ch. 6."]},
 scripture:[["Exodus 3:14, I AM WHO AM",null],["John 4:24, God is a spirit",null],["Job 11:8–9, the 'dimensions' of God",null]],
 sections:[
 {id:"s1",h:"1. After 'whether', 'how': the way of negation",html:`<p>Question 2 asked <em>whether</em> God exists. The natural next question is <em>what</em> he is. Thomas's prologue to question 3 answers with a rule of method that governs qq.3–11:</p>
<div class="quote">"Sed quia de Deo scire non possumus quid sit, sed quid non sit, non possumus considerare de Deo quomodo sit, sed potius quomodo non sit."<span class="src">ST I q.3, prologue (Leonine Latin). "Because we cannot know what God is, but rather what he is not, we cannot consider how God is, but rather how he is not."</span></div>
${RC("f6",`<p>This is the <strong>way of negation</strong> (remotion) from F6, applied systematically. From the Five Ways we know God as the cause of creatures. We now remove from him everything that belongs to creatures <em>as creatures</em>: body, composition, change, time, limitation.</p>`)}
<p>The plan of qq.3–11 follows directly. Each attribute is something removed:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Question</th><th>Attribute</th><th>What is denied</th></tr></thead><tbody>
<tr><td>q.3</td><td>Simplicity</td><td>Composition of any kind</td></tr>
<tr><td>qq.4–6</td><td>Perfection, goodness</td><td>Any lack of act</td></tr>
<tr><td>qq.7–8</td><td>Infinity, omnipresence</td><td>Limitation; being confined to a place</td></tr>
<tr><td>qq.9–10</td><td>Immutability, eternity</td><td>Change; succession in time</td></tr>
<tr><td>q.11</td><td>Unity</td><td>Division; plurality of gods</td></tr></tbody></table></div>
<div class="co warn"><div class="co-h">Common misunderstanding</div><p>Negative theology does not mean we know nothing. A negation is real knowledge: "God is not a body" is true, and it tells us a great deal. What we lack is a <em>concept that captures</em> God's essence (q.12 a.12, Lesson 6). We know <em>that</em> he is and <em>what he is not</em>, and so we know him as distinct from everything else.</p></div>`,
  check:Q("Why does Thomas consider \"how God is not\" rather than \"how God is\"?",[["Because God has no nature at all","No: God's nature is his very being; we simply lack a concept of it."],["Because we cannot know what God is, only what he is not, from creatures","Correct: q.3 prologue. This is the way of negation."],["Because negative statements are easier to prove than positive ones","Not Thomas's reason; the reason lies in the limits of knowledge drawn from creatures."]],1)},
 {id:"s2",h:"2. Not a body; not matter and form (aa.1–2)",html:`<p><strong>Article 1. God is not a body.</strong> Thomas gives three arguments, each resting on the Five Ways:</p>
<ol><li><strong>From the First Way.</strong> No body moves unless it is moved. God is the first, unmoved mover. So he is not a body.</li>
<li><strong>From act and potency.</strong> The first being must be in act and in no way in potency. But a body, being continuous, is divisible to infinity, and so is in potency. So the first being is not a body.</li>
<li><strong>From the Fourth Way.</strong> God is the most noble of beings. A living body is nobler than a dead one, and it lives by something that is not a body (its soul). So the noblest being is not a body.</li></ol>
${RC("f3",`<p>Each step uses the vocabulary of F3: <strong>act</strong> and <strong>potency</strong>, and the definition of motion as the passage from one to the other. If anything in God were still in potency, something prior would be needed to actualise it, and God would not be first.</p>`)}
<p><strong>What about Scripture's bodily language?</strong> Job says God is "higher than heaven… deeper than hell… The measure of him is longer than the earth, and broader than the sea" (Job 11:8–9). Thomas replies that Scripture "puts before us spiritual and divine things under the comparison of corporeal things" (ad 1). Height signifies his power over all, depth his hidden knowledge, length his duration, breadth his love. This is the metaphorical naming you met in F6, section 4.</p>
<p><strong>Article 2. No matter.</strong> Matter is pure potency, and God is pure act. Further, a composite of matter and form is good through its form, so it is good by participation; but the first good is good by its essence. So God is not composed of matter and form. "God is a spirit" (John 4:24).</p>`,
  check:Q("Thomas reads \"the measure of him is longer than the earth\" (Job 11:9) as signifying…",[["God's physical size","He has just shown God is not a body."],["the duration of God's being, by a bodily comparison","Correct: q.3 a.1 ad 1 reads length as duration, breadth as love, height as power, depth as knowledge."],["an error in the book of Job","Thomas never treats Scripture as erring; the figure is intended by the author."]],1)},
 {id:"s3",h:"3. God is his essence, and his essence is his existence (aa.3–4)",html:`<p><strong>Article 3. Nature and suppositum.</strong> A man is not his humanity. "Humanity" includes only what belongs to the definition of man; this man (the <em>suppositum</em>) also has this flesh, these bones, these accidents. In material things nature and suppositum differ because of individual matter. God has no matter, so in him nature and suppositum are the same: he "must be His own Godhead, His own Life, and whatever else is thus predicated of Him" (a.3).</p>
<p><strong>Article 4. Essence and existence.</strong> This is the summit of the question, and of Thomas's metaphysics. \"God is not only His own essence, as shown in the preceding article, but also His own existence.\" Three arguments:</p>
<ol><li><strong>Caused existence.</strong> Whatever a thing has besides its essence is caused, either by the principles of that essence or by an outside cause. Existence cannot be caused by a thing's own essence, since nothing brings itself into being. So if God's existence differed from his essence it would be caused by another, and he would not be the first cause.</li>
<li><strong>Act and potency.</strong> Existence is the act of every form or nature. Where essence differs from existence, essence is to existence as potency to act. There is no potency in God, so his essence is not other than his existence.</li>
<li><strong>Participation.</strong> \"Just as that which has fire, but is not itself fire, is on fire by participation; so that which has existence but is not existence, is a being by participation.\" If God were not his own existence he would be a being by participation, not the first being.</li></ol>
${RC("f4",`<p>In F4 you learned that in every creature essence and <em>esse</em> are really distinct: a phoenix can be understood without knowing whether one exists. Article 4 is the other side of that coin. A being in whom essence and <em>esse</em> are identical can only be one, and it is God: <em>ipsum esse subsistens</em>, subsistent being itself.</p>`)}
<div class="co core"><div class="co-h">Core · I AM WHO AM</div><p>Thomas will later say that "He Who Is" (Exod 3:14) is the most proper name of God, because it signifies not any form but "existence itself" (q.13 a.11). Lesson 6 returns to this. The Catechism reads the Name in the same way: God "is", and in him there is no "becoming" (CCC 213).</p></div>`,
  check:Q("Which argument in q.3 a.4 uses the image of a thing that is \"on fire by participation\"?",[["The argument from motion","That is the First Way, not a.4."],["The argument that a being which has existence but is not existence is a being by participation","Correct: the third argument of a.4."],["The argument that God is not a body","That is a.1."]],1)},
 {id:"s4",h:"4. No genus, no accidents (aa.5–6)",html:`<p><strong>Article 5. God is not in a genus.</strong> A species is made by adding a difference to a genus, as "rational" is added to "animal". The genus is related to the difference as potency to act, so a being in a genus is composite. Further, God's essence is his existence; but "being" cannot be a genus, since every difference would itself be a being and so already included. So God is not a species, and has no genus.</p>
<p>A consequence follows at once: God cannot be <em>defined</em>, because a definition gives genus and difference. Nor can he be <em>demonstrated propter quid</em>, from his essence, because the middle term of such a proof is a definition.</p>
${RC("t3",`<p>This is why q.2 a.2 said God's existence can be shown only by a <strong>demonstration quia</strong>, from effects. We now see the deeper reason: there is no definition of God to serve as a middle term.</p>`)}
<p><strong>Article 6. No accidents.</strong> Three reasons: (1) a subject is in potency to its accidents, and God has no potency; (2) God is his own existence, and "what is" can have something added, but "existence itself" cannot (Boethius); (3) what is essential is prior to what is accidental, and God is absolutely first.</p>
${RC("f4",`<p>Recall the nine categories of accident from F4. Wisdom in Solomon is a <em>quality</em>, an accident he can gain or lose. In God it is not. That is why we say: <strong>God does not have wisdom; he is his wisdom.</strong></p>`)}`,
  check:Q("Why does it follow from a.5 that God cannot be defined?",[["Because definitions are only for material things","Angels have no matter yet fall in a genus of substance."],["Because a definition consists of genus and difference, and God is in no genus","Correct."],["Because God is irrational","God is supremely intelligible in himself; we lack a concept of him."]],1)},
 {id:"s5",h:"5. Altogether simple; not part of anything (aa.7–8)",html:`<p>Article 7 gathers the results: \"There is neither composition of quantitative parts in God, since He is not a body; nor composition of matter and form; nor does His nature differ from His 'suppositum'; nor His essence from His existence; neither is there in Him composition of genus and difference, nor of subject and accident.\" Then it adds general reasons: every composite is posterior to its parts, depends on them, and needs a cause to unite them; and in every composite something is in potency. So the sed contra quotes Augustine: \"God is truly and absolutely simple.\"</p>
<p><strong>Article 8. God enters into composition with nothing.</strong> Thomas names three errors:</p>
<ul><li>God as the <strong>world-soul</strong> (some ancient philosophers, reported by Augustine).</li>
<li>God as the <strong>formal principle</strong> of all things (the Almaricians, condemned at Paris in 1210).</li>
<li>God as <strong>prime matter</strong> (David of Dinant).</li></ul>
<p>Against all three: God is the first efficient cause, and an efficient cause is not part of its effect; he is the first agent, and a part is not first; and he is first being, while every part of a composite is secondary. This excludes <strong>pantheism</strong>: God is in all things (q.8, Lesson 4), but not as their part.</p>
<div class="co bridge"><div class="co-h">The main objection, and the Thomist answer</div><p>If God's wisdom, power and goodness are all identical with his essence, are they identical with each other? Then "wise" and "powerful" would mean the same, and saying "God is powerful" would add nothing to "God is wise" (Plantinga, 1980). Thomas anticipates this in q.13 a.4 (Lesson 6). The names are <em>not synonyms</em>: they signify one simple reality under different concepts, each corresponding to a distinct perfection in creatures which that one reality pre-contains. One simple light is seen under many colours by the prism of creatures. Stump and Kretzmann (1985) defend a version of this; Dolezal (2011) gives a fuller defence. The question is a live one in analytic philosophy of religion.</p></div>
<div class="co apply"><div class="co-h">Apply · simplicity of heart</div><p>The moral sense follows the doctrine. "If thy eye be single, thy whole body shall be lightsome" (Matt 6:22). A person divided among many loves is pulled apart; one who loves God above all becomes, by participation, more one. Thomas's account of the virtues (T8) and the unity of the moral life under charity (T7) continue this.</p></div>`,
  check:Q("David of Dinant's error, refuted in q.3 a.8, was that God is…",[["the world-soul","Some ancients held that; Thomas lists it separately."],["prime matter","Correct."],["a body in the heavens","That is the error of a.1."]],1)}
 ],
 quiz:[
  Q("The prologue of q.3 says that we can know of God…",[["what he is","We cannot know this from creatures."],["what he is not","Correct: hence 'how he is not'."],["nothing at all","We know that he is, and what he is not."],["only what the senses perceive","God is not perceived by the senses."]],1,"ST I q.3 prol.",{bloom:"Remember",terms:["simplicity"],diff:1}),
  Q("Which is NOT one of Thomas's three arguments that God is not a body (a.1)?",[["No body moves without being moved","It is the first argument."],["A body is in potency, being divisible","It is the second."],["The noblest being is not a body","It is the third."],["Bodies are evil","Correct: Manichaeism, not Thomas. Bodies are good."]],3,"ST I q.3 a.1",{bloom:"Understand",terms:[],diff:2}),
  Q("Why can God not be composed of matter and form?",[["Because matter is pure potency, and God is pure act","Correct: q.3 a.2."],["Because forms are illusions","No."],["Because Scripture never mentions matter","Not the argument."],["Because matter is evil","No."]],0,"ST I q.3 a.2",{bloom:"Understand",terms:["actus-purus"],diff:1}),
  Q("In material things, nature and suppositum differ because of…",[["the soul","No."],["individual matter and accidents","Correct: q.3 a.3."],["the will","No."],["divine choice","No."]],1,"ST I q.3 a.3",{bloom:"Remember",terms:["suppositum"],diff:2}),
  Q("The first argument of q.3 a.4 is that if God's existence differed from his essence it would be…",[["infinite","No."],["caused by another, so God would not be first cause","Correct."],["a body","No."],["accidental to his will","No."]],1,"ST I q.3 a.4",{bloom:"Understand",terms:["esse"],diff:2}),
  Q("\"God does not have wisdom; he is his wisdom\" follows most directly from…",[["a.5 (no genus)","Related, but not the direct basis."],["a.6 (no accidents)","Correct: in creatures wisdom is a quality, an accident."],["a.8 (no composition with others)","No."],["a.1 (not a body)","No."]],1,"ST I q.3 a.6",{bloom:"Apply",terms:["simplicity"],diff:2}),
  Q("Why can God's existence be shown only by a demonstration quia?",[["Because no one has thought of a better proof","No."],["Because God has no definition to serve as the middle term of a propter quid demonstration","Correct: q.3 a.5 with q.2 a.2."],["Because faith forbids it","No."],["Because God is in the genus of substance","He is in no genus."]],1,"ST I q.3 a.5; q.2 a.2",{bloom:"Analyse",terms:["demonstration-quia"],diff:3}),
  Q("Which modern objection to divine simplicity does Thomas's q.13 a.4 answer?",[["That simplicity makes all divine names synonyms","Correct: they signify one reality under different concepts."],["That simplicity requires God to be a body","No."],["That simplicity contradicts the Five Ways","No: it is derived from them."],["That simplicity denies God exists","No."]],0,"ST I q.13 a.4",{bloom:"Analyse",terms:["simplicity"],diff:3}),
  Q("Which name does Thomas call most proper to God, because it signifies existence itself?",[["Lord","No."],["He Who Is","Correct: q.13 a.11, from Exod 3:14."],["Creator","A relative name."],["Judge","No."]],1,"ST I q.13 a.11",{bloom:"Remember",terms:["esse"],diff:1}),
  Q("Pantheism is excluded by which article?",[["q.3 a.8, God enters into composition with nothing","Correct."],["q.3 a.1","That excludes body."],["q.3 a.3","That concerns nature and suppositum."],["q.2 a.1","That concerns self-evidence."]],0,"ST I q.3 a.8",{bloom:"Apply",terms:["composition"],diff:2}),
  Q("Every composite, Thomas argues, needs…",[["a cause uniting its components","Correct: q.3 a.7."],["a body","No."],["to be eternal","No."],["to be evil","No."]],0,"ST I q.3 a.7",{bloom:"Remember",terms:["composition"],diff:1})
 ],
 construct:{q:"Whether God is altogether simple?",ref:"ST I q.3 a.7",
  model:{obj:"It seems not: things from God imitate him, and all creatures are composite, so God is composite; further, whatever is best must be given to God, and among us composite things are better than simple ones (as mixed bodies than elements).",sc:"Augustine (De Trin. iv, 6, 7): \"God is truly and absolutely simple.\"",resp:"From the preceding articles: no quantitative parts, matter and form, nature and suppositum, essence and existence, genus and difference, subject and accident. Further: every composite is posterior to its components and depends on them; needs a cause to unite them; and has potency and act in it. God is first, uncaused, and pure act. So he is altogether simple.",rep:"Things from God imitate him as effects imitate their first cause, which is simple; their composition belongs to their being caused. Among creatures composites are better because one created simple thing cannot have the whole perfection; but God has all perfection in his one simple being."},
  rubric:["Objection argues from creatures' likeness to God or from the excellence of composites.","Sed contra quotes Augustine.","Respondeo gathers the six denials of aa.1–6.","Respondeo adds a general argument (posteriority, need of a cause, potency).","Reply explains why created perfection requires composition but divine perfection does not."]},
 drill:{title:"Order the articles of q.3",parts:["Is God a body? (a.1)","Is he composed of matter and form? (a.2)","Is he the same as his essence or nature? (a.3)","Are essence and existence the same in him? (a.4)","Is he in a genus? (a.5)","Are there accidents in him? (a.6)","Is he altogether simple? (a.7)","Does he enter into composition with other things? (a.8)"]},
 connections:`<p><strong>Back.</strong> F3 (act and potency) and F4 (essence and <em>esse</em>) supply every premise; the First and Fourth Ways (T3 L1) supply the starting point. F6 named the way of negation; this lesson uses it.</p><p><strong>Forward.</strong> Simplicity is the hinge of the treatise. It grounds perfection (L3), infinity (L4), immutability and eternity (L5), and it is why divine names need analogy (L6). In T4 it is what makes the divine relations identical with the essence, so that three persons are not three gods. In T11 the Incarnation adds no composition to the Word: the human nature is united to him without changing him.</p><p><strong>Psychology.</strong> The "integration" of the person studied in personality psychology (P10) is a created, partial image of what God is perfectly. Fragmentation of motive is a mark of the wounded will (P1b).</p>`},

// ===================== L3 PERFECTION & GOODNESS =====================
{id:"t3l3",ord:3,code:"T3 · Lesson 3",title:"Perfection and goodness: all excellence is in God (ST I qq.4–6)",
 outcomes:["Explain what 'perfect' means and why it is said of God although he was never 'made' (q.4 a.1).","Show why all perfections of creatures pre-exist in God, using the distinction between univocal and equivocal causes (q.4 a.2).","Explain in what sense creatures are like God and why God is not like creatures (q.4 a.3).","State why being and goodness are convertible and why goodness has the aspect of a final cause (q.5).","Explain why God alone is good by essence, yet creatures are formally good by their own goodness (q.6)."],
 prereq:["perfection","eminence","analogy","univocal","transcendentals","good-ratio","participation"],
 recall:[
  ["t3l2","Why is God his own existence (q.3 a.4)?","Because otherwise his existence would be caused by another; because existence is the act of every essence and there is no potency in God; and because what has existence without being it is a being by participation."],
  ["f2","What is the difference between univocal, equivocal and analogical predication?","Univocal: same name, same meaning (dog said of two dogs). Equivocal: same name, unrelated meanings (bank of a river, a bank for money). Analogical: same name, related meanings ordered to one (healthy said of a man, food, a complexion)."],
  ["t3","What does the Fourth Way argue from?","From the gradation of perfections in things (more and less good, true, noble) to a maximum that is the cause of these perfections in all things: God."],
  ["f3","What is a final cause?","That for the sake of which something is done or comes to be: the end. It is the 'cause of causes' because it moves the agent to act."]],
 reading:{primary:[["ST I q.4 aa.1–3 (perfection)",NA("1004.htm")],["ST I q.5 aa.1–6 (goodness in general)",NA("1005.htm")],["ST I q.6 aa.1–4 (the goodness of God)",NA("1006.htm")],["CCC 41–43 (our language about God)",'https://www.vatican.va/archive/ENG0015/__P9.HTM']],
  secondary:["Aertsen, J.A. (1996) Medieval Philosophy and the Transcendentals: The Case of Thomas Aquinas. Leiden: Brill.","Wippel, J.F. (2000) The Metaphysical Thought of Thomas Aquinas. Washington, DC: CUA Press, ch. 11.","Stump, E. (2003) Aquinas. London: Routledge, ch. 2 ('Being and goodness').","MacDonald, S. (ed.) (1991) Being and Goodness: The Concept of the Good in Metaphysics and Philosophical Theology. Ithaca: Cornell University Press."]},
 scripture:[["Mark 10:18, None is good but one, that is God",null],["Wisdom 13:5, the beauty of creatures",null],["Matthew 5:48, Be you therefore perfect",null]],
 sections:[
 {id:"s1",h:"1. What 'perfect' means (q.4 a.1)",html:`<p>"Perfect" comes from <em>per-factum</em>, "thoroughly made". So the objection asks: how can God be perfect, if he was never made? Thomas accepts the etymology and corrects the meaning. Gregory the Great is quoted: \"Though our lips can only stammer, we yet chant the high things of God.\"</p>
<p>A made thing is called perfect when it has been brought from potency to full act. So the word, by extension, signifies \"whatever is not wanting in actuality, whether this be by way of perfection or not\" (ad 1). God is perfect in this extended sense: he lacks no act.</p>
${RC("t3l2",`<p>Lesson 2 showed God is pure act and his own existence. Perfection is the same truth stated positively. What is wholly in act lacks nothing; what lacks nothing is perfect.</p>`)}
<p><strong>A first answer to the Pythagoreans.</strong> Some ancients refused to call the first principle "best", because they took it to be matter, which is merely potential and so most imperfect. But God is the first principle "not material, but in the order of efficient cause", and the efficient cause is in act. So the first principle is the most perfect (a.1).</p>
<div class="co warn"><div class="co-h">Common misunderstanding</div><p>Evolutionary or developmental pictures sometimes assume that the most perfect comes last, out of the least. Thomas grants that, <em>in the order of generation</em>, the imperfect comes first (the seed before the tree). But the seed itself comes from a tree already in act. The first cause of any process must have the perfection it produces.</p></div>`,
  check:Q("In what sense is God called 'perfect', though he was never made?",[["In no sense; the word is improper","Thomas says it is used with stammering lips, but truly."],["As not wanting in any actuality","Correct: q.4 a.1 ad 1."],["As having finished developing","God does not develop."]],1)},
 {id:"s2",h:"2. All perfections are in God (q.4 a.2)",html:`<p>\"All created perfections are in God.\" Two arguments:</p>
<ol><li><strong>From causality.</strong> Whatever perfection is in an effect must be in its cause, either in the same way (a <em>univocal</em> agent: man begets man) or in a higher way (an <em>equivocal</em> agent: the sun produces heat and life in things without being itself a hot or living body in their way). God is the first efficient cause of all things, and causes them as an equivocal agent. So all perfections pre-exist in him, in a more eminent way.</li>
<li><strong>From God's being.</strong> God is subsisting being itself (q.3 a.4). All perfections are perfections of being: a thing is perfect to the degree it has being in some way. So subsisting being itself cannot lack any perfection of being.</li></ol>
${RC("f2",`<p><strong>Univocal / equivocal</strong> here are kinds of <em>cause</em>, built on the logical distinction from F2. A univocal cause shares its effect's species; an equivocal cause does not, and so has the effect's perfection in another, higher mode. This is the causal root of <strong>analogy</strong> (F4, section 5).</p>`)}
${RC("f6",`<p>This is the <strong>way of eminence</strong> from F6. Wisdom, life, goodness are in God not as in Solomon, but as in their source: without limit, without composition, identical with his being.</p>`)}
<p><strong>Which perfections?</strong> Only <em>pure</em> perfections, those whose meaning includes no limitation (being, life, wisdom, goodness), are in God formally. <em>Mixed</em> perfections, which include a creaturely limit in their very meaning (reasoning step by step, having a body, courage in the face of death), are in him only virtually: he can cause them, as the sun can cause heat in a stone, but he does not have them in their own mode. Thomas explains this fully in q.13 a.3 (Lesson 6).</p>`,
  check:Q("The sun producing heat and life, without being a living body in their way, illustrates…",[["a univocal agent","A univocal agent shares the species."],["an equivocal agent, whose effects pre-exist in it more eminently","Correct: q.4 a.2."],["an accidental cause","Not the point."]],1)},
 {id:"s3",h:"3. Creatures are like God; God is not like creatures (q.4 a.3)",html:`<p>Likeness is agreement in form. When things share the same form in the same way they are equal (two white walls). When they share a form unequally, one is more, the other less (a pale and a brilliant white). But when an agent is not in the same genus as its effect, the effect receives a likeness that is only \"according to some sort of analogy; as existence is common to all\" (a.3).</p>
<p>This is how creatures resemble God. Then comes a crucial asymmetry (ad 4):</p>
<div class="quote">"For, we say that a statue is like a man, but not conversely; so also a creature can be spoken of as in some sort like God; but not that God is like a creature."<span class="src">ST I q.4 a.3 ad 4 · Dominican tr. (1920)</span></div>
${RC("f4",`<p>This is the <strong>analogy of being</strong> from F4: "being" is said of God and creatures neither univocally nor equivocally, but by an order of one to the other. The creature has being by participation; God is being.</p>`)}
<div class="co bridge"><div class="co-h">The Magisterium on the limits of likeness</div><p><span class="voice">Magisterium</span>The Fourth Lateran Council (1215) teaches that "between Creator and creature no similitude can be expressed without implying a greater dissimilitude" (DS 806; quoted in CCC 43). Thomas's asymmetry is the same principle.</p></div>`,
  check:Q("Why does Thomas say the creature is like God, but God is not like the creature?",[["Because creatures are more perfect than God","Reversed."],["Because the creature has from God, by participation, what God has by essence, as a statue resembles a man","Correct: q.4 a.3 ad 4."],["Because there is no likeness at all","There is likeness by analogy."]],1)},
 {id:"s4",h:"4. Goodness and being (q.5)",html:`<p>Question 5 steps back from God to goodness in general, because one cannot ask whether God is good without knowing what good is.</p>
<ol><li><strong>Convertible with being (a.1).</strong> \"Goodness and being are really the same, and differ only in idea.\" Good is what is desirable; a thing is desirable insofar as it is perfect; it is perfect insofar as it is actual; it is actual by existing. So whatever is, insofar as it is, is good.</li>
<li><strong>Being comes first in idea (a.2).</strong> The first thing the intellect conceives is being. Good adds to being the relation to appetite.</li>
<li><strong>Every being is good (a.3).</strong> \"Every being, as being, is good.\" Evil is therefore not a being but a lack (q.48; you met this in T5 as privation).</li>
<li><strong>Good is a final cause (a.4).</strong> Since good is what all desire, it has the character of an end.</li>
<li><strong>The three kinds of good (a.6).</strong> The <em>virtuous</em> (bonum honestum: desirable in itself), the <em>useful</em> (desirable for something else), and the <em>pleasant</em> (the rest of appetite in the good attained).</li></ol>
${RC("f4",`<p>Good is one of the <strong>transcendentals</strong> you met in F4: properties convertible with being. Being, one, true, good: each is the same reality as being, seen under a different relation (to itself, undivided; to intellect, true; to appetite, good).</p>`)}
${RC("t5",`<p>From T5: evil is a <strong>privation</strong>, the absence of a good that ought to be there (blindness in an eye, not in a stone). Question 5 explains why: if every being as such is good, evil cannot be a being.</p>`)}
<div class="co apply"><div class="co-h">Apply · the honest, the useful and the pleasant</div><p>Most failures in the moral life come from treating a useful or pleasant good as if it were the honest good, the end. Money is useful; pleasure is the rest of desire; neither is the last end (I-II q.2, T6). Psychology's distinction between intrinsic and extrinsic motivation (Ryan &amp; Deci, 2000) overlaps with, but is not the same as, the honest/useful distinction: intrinsic motives can still aim at lesser goods.</p></div>`,
  check:Q("According to q.5 a.1, being and goodness are…",[["really distinct","No."],["really the same, differing only in idea","Correct."],["unrelated","No."]],1)},
 {id:"s5",h:"5. God's goodness (q.6)",html:`<p>Now Thomas returns to God.</p>
<ol><li><strong>God is good (a.1).</strong> Every agent makes its like, so every effect, in desiring its own perfection, desires a likeness of its cause. God, the first cause, is therefore desirable, and good.</li>
<li><strong>The supreme good (a.2).</strong> Not the highest member of a series of goods, but good \"simply\", as the source of all goodness beyond every genus.</li>
<li><strong>Good by essence, God alone (a.3).</strong> A creature is perfect in three ways: in its being, in its added powers and accidents, and in reaching its end. None of these is identical with its essence. In God all three are his essence. So he alone is good essentially. This is the meaning of the Lord's words: \"None is good but one, that is God\" (Mark 10:18).</li>
<li><strong>All things are good by the divine goodness, and by their own (a.4).</strong> Against Plato, things are not good by a separate Idea of Good. Yet they depend on God's goodness as exemplar, efficient and final cause.</li></ol>
<div class="quote">"Everything is therefore called good from the divine goodness, as from the first exemplary, effective, and final principle of all goodness. Nevertheless, everything is called good by reason of the similitude of the divine goodness belonging to it, which is formally its own goodness, whereby it is denominated good. And so of all things there is one goodness, and yet many goodnesses."<span class="src">ST I q.6 a.4 · Dominican tr. (1920)</span></div>
${RC("t5",`<p>This is the same balance as <strong>secondary causes</strong> in T5: creatures really act, yet God works in every agent. Here: creatures are really good, with goodness of their own, yet that goodness is a received likeness of his.</p>`)}`,
  check:Q("q.6 a.4 concludes that \"of all things there is one goodness, and yet many goodnesses\". The 'many' refers to…",[["many gods","No."],["each creature's own formal goodness, a likeness of God's","Correct."],["Plato's separate Ideas","Thomas rejects these as separate."]],1)}
 ],
 quiz:[
  Q("'Perfect' said of God means…",[["brought from potency to act","God has no potency."],["not wanting in any actuality","Correct: q.4 a.1 ad 1."],["finished in time","No."],["morally improved","No."]],1,"ST I q.4 a.1",{bloom:"Remember",terms:["perfection"],diff:1}),
  Q("Why did some ancients not call the first principle 'most perfect'?",[["They thought it was matter, which is merely potential","Correct: q.4 a.1."],["They were atheists","Not the stated reason."],["They thought it was a person","No."],["They denied all change","That was Parmenides, and not the point here."]],0,"ST I q.4 a.1",{bloom:"Remember",terms:[],diff:2}),
  Q("An equivocal cause has its effect's perfection…",[["in the same species","That is univocal."],["in a higher, more eminent way","Correct: q.4 a.2."],["not at all","Then it could not cause it."],["only by accident","No."]],1,"ST I q.4 a.2",{bloom:"Understand",terms:["univocal","eminence"],diff:2}),
  Q("Which of these is a mixed perfection, in God only virtually?",[["Wisdom","Pure perfection."],["Life","Pure perfection."],["Reasoning step by step","Correct: it includes the limit of discursive thought."],["Goodness","Pure perfection."]],2,"ST I q.13 a.3",{bloom:"Apply",terms:["perfection"],diff:3}),
  Q("\"A statue is like a man, but not conversely\" illustrates…",[["that God is like the creature","Reversed."],["the one-way likeness of creature to God","Correct: q.4 a.3 ad 4."],["univocal likeness","No."],["pantheism","No."]],1,"ST I q.4 a.3",{bloom:"Understand",terms:["analogy"],diff:2}),
  Q("Lateran IV (1215) teaches that between Creator and creature…",[["no likeness exists","It says likeness implies greater unlikeness."],["every likeness implies a greater unlikeness","Correct: DS 806; CCC 43."],["there is perfect likeness","No."],["only moral likeness exists","No."]],1,"DS 806; CCC 43",{bloom:"Remember",terms:[],diff:2}),
  Q("Being and goodness differ in that goodness adds…",[["a real accident","It adds nothing real."],["the aspect of desirability","Correct: q.5 a.1."],["a body","No."],["moral rightness","Not in this sense."]],1,"ST I q.5 a.1",{bloom:"Understand",terms:["good-ratio","transcendentals"],diff:2}),
  Q("The three divisions of the good in q.5 a.6 are…",[["true, good, beautiful","Transcendentals."],["virtuous (honest), useful, pleasant","Correct."],["natural, supernatural, preternatural","No."],["individual, common, divine","No."]],1,"ST I q.5 a.6",{bloom:"Remember",terms:["good-ratio"],diff:1}),
  Q("God alone is good by essence because…",[["only he is desired","No."],["in him being, operation and end are identical with his essence","Correct: q.6 a.3."],["creatures are evil","No: every being is good."],["he chose to be","No."]],1,"ST I q.6 a.3",{bloom:"Analyse",terms:["good-ratio"],diff:3}),
  Q("Against Plato, Thomas holds that creatures are good…",[["by a separate Idea of the Good","That is Plato."],["formally by their own goodness, which is a likeness of God's","Correct: q.6 a.4."],["not at all","No."],["only in God's mind","No."]],1,"ST I q.6 a.4",{bloom:"Analyse",terms:["participation"],diff:3})
 ],
 construct:{q:"Whether the perfections of all things are in God?",ref:"ST I q.4 a.2",
  model:{obj:"It seems not: God is simple, but the perfections of things are many and diverse; and opposites cannot be together, but the perfections of things are opposed (each species is perfected by its difference).",sc:"Dionysius (Div. Nom. v): God \"in His one existence prepossesses all things\".",resp:"All created perfections are in God. First, whatever perfection is in an effect is in its efficient cause, in the same way if univocal, more eminently if equivocal; God is the first cause of all things. Second, God is subsisting being itself, and all perfections are perfections of being; so he lacks none.",rep:"What is many and divided in creatures is one and simple in God, as the sun, being one, has in itself the powers of many diverse effects. Opposed perfections exclude each other in creatures because each is limited; in God they pre-exist as in their simple source."},
  rubric:["Objection argues from simplicity or the opposition of perfections.","Sed contra cites Dionysius.","Respondeo gives the argument from efficient causality (univocal/equivocal).","Respondeo gives the argument from subsisting being.","Reply uses the image of one source with many effects."]},
 drill:{title:"Follow the steps of q.5 a.1: why being is good",parts:["Good is what all desire","A thing is desirable insofar as it is perfect","A thing is perfect insofar as it is actual","A thing is actual by existing","So being and goodness are really the same, differing in idea"]},
 connections:`<p><strong>Back.</strong> L2's simplicity explains why many perfections can be one in God. F4's transcendentals and analogy, and F2's univocal/equivocal distinction, are used throughout.</p><p><strong>Forward.</strong> q.5 grounds the whole moral part (T6): the will is moved by the good, and the last end is the supreme good. q.6 grounds creation's purpose (T5): God creates to communicate his goodness. In T7 charity loves God as the supreme good.</p><p><strong>Psychology.</strong> Affective science studies approach and avoidance (P8). Thomas's claim that every appetite tends to some good, even when it chooses badly, is a philosophical counterpart: the addict seeks relief or pleasure, real goods disordered.</p>`},

// ===================== L4 INFINITY & PRESENCE =====================
{id:"t3l4",ord:4,code:"T3 · Lesson 4",title:"Infinity and omnipresence: God in all things (ST I qq.7–8)",
 outcomes:["Distinguish infinity of matter from infinity of form and explain why God is infinite (q.7 a.1).","Explain why no creature is absolutely infinite (q.7 a.2) and summarise Thomas's view on actual infinite magnitude and multitude (aa.3–4), noting where it is contested.","Show that God is in all things, and innermostly, as the cause of their being (q.8 a.1).","Explain how God is in all things by essence, presence and power, and how he is present in a special way by grace (q.8 a.3).","Distinguish omnipresence from pantheism and from spatial extension."],
 prereq:["infinity-div","omnipresence","participation","esse","conservation","mission"],
 recall:[
  ["f4","How does essence relate to esse in a creature, and what does this do to esse?","Essence is a potency that receives esse and limits it. A creature has a determinate amount of being because its being is received in a determinate essence."],
  ["t3l2","Why does God enter into composition with nothing (q.3 a.8)?","Because he is the first efficient cause, and an efficient cause is not part of its effect; and because he is first, while every part of a composite is secondary. This rules out pantheism."],
  ["t5","What is conservation?","God's continual giving of being to creatures, without which they would fall into nothing. It is not a new act but the continuation of creation (ST I q.104 a.1)."],
  ["t4","What is the invisible mission of a divine person?","His eternal procession together with a new presence in a creature by sanctifying grace, in which God dwells as the known in the knower and the beloved in the lover (ST I q.43 a.3)."]],
 reading:{primary:[["ST I q.7 aa.1–4 (the infinity of God)",NA("1007.htm")],["ST I q.8 aa.1–4 (the existence of God in things)",NA("1008.htm")],["Augustine, Confessions III.6.11 ('more inward than my inmost')",'https://www.newadvent.org/fathers/110103.htm'],["CCC 300–301",'https://www.vatican.va/archive/ENG0015/__P1D.HTM']],
  secondary:["Wippel, J.F. (2000) The Metaphysical Thought of Thomas Aquinas, ch. 4 (participation and limitation of act).","Clarke, W.N. (1952) 'The limitation of act by potency: Aristotelianism or Neoplatonism?', The New Scholasticism, 26(2), pp. 167–194.","Moore, A.W. (2019) The Infinite. 3rd edn. London: Routledge (for the mathematical infinite).","Garrigou-Lagrange, R. (1934) God: His Existence and His Nature, vol. 2. St Louis: Herder."]},
 scripture:[["Jeremiah 23:24, Do not I fill heaven and earth?",null],["Psalm 138 (139):7–8, Whither shall I flee from thy face?",null],["Acts 17:27–28, In him we live and move and are",null],["Psalm 144 (145):3, of his greatness there is no end",null]],
 sections:[
 {id:"s1",h:"1. Two infinities: of matter and of form (q.7 a.1)",html:`<p>"Infinite" means unlimited. But a thing can be unlimited in two opposite ways:</p>
<div class="tablewrap"><table class="t"><thead><tr><th></th><th>Infinity of matter</th><th>Infinity of form</th></tr></thead><tbody>
<tr><td>What limits what</td><td>Form limits matter, giving it determinate being</td><td>Matter (or any receiving potency) limits form, contracting it to this one thing</td></tr>
<tr><td>Without the limit</td><td>Matter without form is formless and indeterminate</td><td>Form not received in anything is full and unrestricted</td></tr>
<tr><td>Is it perfection?</td><td>No: \"infinite as attributed to matter, has the nature of something imperfect\"</td><td>Yes: it has the nature of something perfect</td></tr></tbody></table></div>
<p>Now apply this to being. \"Being is the most formal of all things\" (a.1). God's being is not received in any essence; he is his own subsistent being (q.3 a.4). So:</p>
<div class="quote">"Since therefore the divine being is not a being received in anything, but He is His own subsistent being as was shown above (I:3:4), it is clear that God Himself is infinite and perfect."<span class="src">ST I q.7 a.1 · Dominican tr. (1920)</span></div>
${RC("f4",`<p>This is the principle of <strong>limitation of act by potency</strong> you met in F4: an act (here, <em>esse</em>) is limited only by the potency (the essence) that receives it. Remove the receiving potency and the act is unlimited. Every creature is a cup of a certain size; God is not water in a cup.</p>`)}`,
  check:Q("Why is infinity of matter an imperfection but infinity of form a perfection?",[["Because matter is evil","No."],["Because matter is perfected by being limited by form, while form is contracted by being received in matter","Correct: q.7 a.1."],["Because form is bigger than matter","Not a matter of size."]],1)},
 {id:"s2",h:"2. Nothing else is absolutely infinite (q.7 aa.2–4)",html:`<p><strong>Article 2.</strong> Creatures can be infinite <em>relatively</em> but never <em>absolutely</em>. Prime matter is relatively infinite in its potency to many forms. A separated form, such as an angel, is relatively infinite in that it is not limited by matter. But every creature's being is received in its essence, so \"its being is received and contracted to a determinate nature. Hence it cannot be absolutely infinite.\"</p>
${RC("t5",`<p>Each angel is its own species (T5). That makes an angel unlimited by matter, but still finite: its whole being is the being of <em>this</em> kind of thing, received from God.</p>`)}
<p><strong>Articles 3–4: actual infinities in nature.</strong> Thomas argues that no body can be actually infinite in size, and that an actually infinite multitude cannot exist, because every multitude falls under some determinate species of number. A <em>potentially</em> infinite multitude (you can always add one more; a line can always be divided further) is possible.</p>
<div class="co warn"><div class="co-h">Contested · read with care</div><p>Since Cantor (1874, 1895), mathematics works with actually infinite sets in a consistent way, and many philosophers think Thomas's argument in a.4 fails as stated: "every multitude has a number" assumes all numbers are finite. Thomists divide. Some restrict a.4 to physical, real multitudes, not mathematical objects; others think it should be revised. Note also that in <em>De aeternitate mundi</em> (c.1271) Thomas declines to say it has been proved that an infinite multitude of souls is impossible. What matters for De Deo Uno is untouched: God's infinity is not a quantity at all, but the absence of any limit to his being.</p></div>`,
  check:Q("Thomas holds that a potentially infinite multitude…",[["is impossible","Only the actually infinite is excluded."],["is possible, as when a magnitude can always be divided further","Correct: q.7 a.4."],["is the same as God's infinity","God's infinity is not quantitative."]],1)},
 {id:"s3",h:"3. God is in all things, and innermostly (q.8 a.1)",html:`<p>Thomas now asks how the infinite God relates to finite things. His answer:</p>
<div class="quote">"God is in all things; not, indeed, as part of their essence, nor as an accident, but as an agent is present to that upon which it works."<span class="src">ST I q.8 a.1 · Dominican tr. (1920)</span></div>
<p>The argument runs in four steps:</p>
<ol><li>An agent must be joined to what it acts on immediately, touching it by its power.</li>
<li>God is being itself by his essence, so created being is his proper effect, \"as to ignite is the proper effect of fire\".</li>
<li>God causes this effect not only when things begin to be, but as long as they are preserved in being, \"as light is caused in the air by the sun as long as the air remains illuminated\".</li>
<li>Being is what is most intimate to each thing and most deeply in it, since it is formal with respect to everything in the thing. \"Hence it must be that God is in all things, and innermostly.\"</li></ol>
${RC("t5",`<p>This is <strong>conservation</strong> from T5, seen from God's side. Because God is always giving being, he is always present to what he gives it to. The deist picture of God as a watchmaker who leaves the watch is excluded twice: by conservation and by omnipresence.</p>`)}
<div class="co core"><div class="co-h">Augustine's phrase</div><p>"Thou wert more inward to me than my most inward part, and higher than my highest" (<em>interior intimo meo et superior summo meo</em>; Confessions III.6.11). Thomas gives the metaphysical reason: God is innermost because <em>esse</em> is innermost, and he is its cause; he is highest because he is not part of anything (q.3 a.8).</p></div>`,
  check:Q("Why is God 'innermostly' in things, according to q.8 a.1?",[["Because he is part of their essence","Excluded: q.3 a.8."],["Because he causes their being, and being is what is most intimate in each thing","Correct."],["Because he is a fine invisible substance","No: he is not a body."]],1)},
 {id:"s4",h:"4. Everywhere: by essence, presence and power (q.8 aa.2–4)",html:`<p><strong>Article 2.</strong> God is in every place, not by being contained in it or by being spread out through it, but by giving it being and its capacity to contain. A body fills a place by excluding other bodies; God fills every place without excluding anything (ad 3). And he is wholly in each place, not partly here and partly there.</p>
<p><strong>Article 3.</strong> The classic formula, taken from Gregory the Great:</p>
<div class="quote">"Therefore, God is in all things by His power, inasmuch as all things are subject to His power; He is by His presence in all things, as all things are bare and open to His eyes; He is in all things by His essence, inasmuch as He is present to all as the cause of their being."<span class="src">ST I q.8 a.3 · Dominican tr. (1920)</span></div>
<p>Each phrase excludes an error: some said only spiritual things are subject to God's power (Manichees); some said lower things escape his knowledge; some said God created only the first creatures, and these the rest.</p>
<p><strong>A second, special presence.</strong> God is also in things \"as the object of operation is in the operator\", as the known is in the knower and the beloved in the lover. \"In this second way God is especially in the rational creature which knows and loves Him actually or habitually\" (a.3). This is the indwelling by grace.</p>
${RC("t4",`<p>This special presence is the <strong>invisible mission</strong> of T4 (q.43 a.3). The Son and Spirit are sent into the soul when God becomes present in a new way, as known and loved. Omnipresence is the floor; grace builds a temple on it.</p>`)}
<p><strong>Article 4.</strong> To be everywhere primarily and absolutely belongs to God alone.</p>`,
  check:Q("In the formula 'by essence, presence and power', 'presence' means that…",[["God is a body in every place","No."],["all things are bare and open to his eyes","Correct: q.8 a.3."],["God is present only in the just","That is the special presence by grace."]],1)},
 {id:"s5",h:"5. Omnipresence, pantheism and the presence of God in prayer",html:`<p>Three pictures of God and the world are ruled out:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Picture</th><th>Claim</th><th>Why excluded</th></tr></thead><tbody>
<tr><td>Deism</td><td>God made the world and is now absent</td><td>Conservation (T5); q.8 a.1</td></tr>
<tr><td>Pantheism</td><td>God is the world, or its soul or matter</td><td>q.3 a.8 (L2): God is in all things, but not as a part</td></tr>
<tr><td>Spatial theism</td><td>God is a vast substance extended through space</td><td>q.3 a.1 (L2): God is not a body; q.8 a.2: wholly in each place</td></tr></tbody></table></div>
<p>Scripture gives the Thomist picture: \"Do not I fill heaven and earth, saith the Lord?\" (Jer 23:24); \"Whither shall I go from thy spirit? or whither shall I flee from thy face?\" (Ps 138:7); \"In him we live and move and are\" (Acts 17:28).</p>
<div class="co apply"><div class="co-h">Apply · the practice of the presence of God</div><p>Spiritual writers from Teresa of Avila to Brother Lawrence teach recollection: turning attention to God who is already present. The doctrine explains why this is not imagination. God is not far off to be reached by effort; he is the innermost cause of my being at this moment. Prayer adds the second mode: knowing and loving him there (T9a).</p></div>
<div class="co bridge"><div class="co-h">Psychology</div><p>Mindfulness-based interventions train non-judgemental attention to present experience and have moderate evidence for reducing anxiety and depression symptoms (Goldberg et al., 2018, meta-analysis of 142 RCTs, <em>Clinical Psychology Review</em>, 59, pp. 52–60). Christian recollection overlaps in technique (attention, return from distraction) but differs in object: not the present moment as such, but the person of God present in it. A Catholic clinician can use attention-training while respecting this difference (P1).</p></div>`,
  check:Q("Which picture is excluded by q.3 a.8 rather than by q.8?",[["Deism","Excluded by conservation and q.8 a.1."],["Pantheism","Correct: God enters into composition with nothing."],["The indwelling of grace","That is affirmed, not excluded."]],1)}
 ],
 quiz:[
  Q("God is infinite because…",[["he is very large","Not quantitative."],["his being is not received in anything that limits it","Correct: q.7 a.1."],["he has many parts","No."],["he lasts forever","That is eternity, a different attribute."]],1,"ST I q.7 a.1",{bloom:"Understand",terms:["infinity-div"],diff:1}),
  Q("Infinity attributed to matter is…",[["a perfection","No."],["an imperfection, like formlessness","Correct."],["the same as divine infinity","Opposite."],["impossible to conceive","No."]],1,"ST I q.7 a.1",{bloom:"Remember",terms:["infinity-div"],diff:2}),
  Q("An angel is…",[["absolutely infinite","No: q.7 a.2."],["relatively infinite (not limited by matter), but finite in being","Correct."],["infinite in magnitude","No."],["identical with its esse","Only God is."]],1,"ST I q.7 a.2",{bloom:"Apply",terms:["angel"],diff:2}),
  Q("Which claim in q.7 is most contested by modern mathematics?",[["God is infinite","Not a mathematical claim."],["An actually infinite multitude cannot exist","Correct: set theory treats actual infinities consistently."],["Matter is limited by form","Not mathematical."],["Being is most formal","Not mathematical."]],1,"ST I q.7 a.4",{bloom:"Evaluate",terms:[],diff:3}),
  Q("God is in all things as…",[["part of their essence","No."],["an accident","No."],["an agent present to what it works on","Correct: q.8 a.1."],["a body filling them","No."]],2,"ST I q.8 a.1",{bloom:"Remember",terms:["omnipresence"],diff:1}),
  Q("Thomas compares God's continual causing of being to…",[["a builder and a house","That is the deist image he rejects."],["the sun's lighting of the air","Correct: q.8 a.1."],["a mother and child","No."],["a king and his kingdom","No."]],1,"ST I q.8 a.1",{bloom:"Remember",terms:["conservation"],diff:1}),
  Q("\"God is in all things by His power\" is directed against those who said…",[["only spiritual things are subject to God's power","Correct: q.8 a.3."],["God does not know lower things","That is answered by 'presence'."],["God created only the first creatures","That is answered by 'essence'."],["God is a body","No."]],0,"ST I q.8 a.3",{bloom:"Analyse",terms:["omnipresence"],diff:3}),
  Q("God's special presence in the just is that of…",[["a body in a place","No."],["the known in the knower and the beloved in the lover","Correct: q.8 a.3."],["a part in a whole","No."],["a cause in its effect only","That is the common mode."]],1,"ST I q.8 a.3; q.43 a.3",{bloom:"Understand",terms:["mission"],diff:2}),
  Q("How does God fill a place differently from a body?",[["He excludes other things from it","A body does that."],["He fills it without excluding anything, by giving it being","Correct: q.8 a.2 ad 3."],["Only partly","He is wholly in each place."],["He does not fill places","He fills every place."]],1,"ST I q.8 a.2",{bloom:"Understand",terms:["omnipresence"],diff:2}),
  Q("\"More inward to me than my most inward part\" is from…",[["Thomas, ST I q.8","Thomas gives the reason; the phrase is Augustine's."],["Augustine, Confessions III","Correct."],["Dionysius","No."],["Boethius","No."]],1,"Conf. III.6.11",{bloom:"Remember",terms:[],diff:1})
 ],
 construct:{q:"Whether God is in all things?",ref:"ST I q.8 a.1",
  model:{obj:"It seems not: what is above all things is not in all things; God is above all (Ps 112:4). Further, what is in something is contained by it; but God contains things rather than being contained.",sc:"An operation of a thing is where the thing is. God operates in all things (Isa 26:12, in the Summa's text: \"Thou hast wrought all our works in [Vulgate: 'for'] us\"). So God is in all things.",resp:"God is in all things, not as part of their essence or as an accident, but as an agent is present to what it acts on. Created being is his proper effect, caused not only at the beginning but as long as things exist, as light in the air by the sun. Being is innermost in each thing. So God is in all things, and innermostly.",rep:"God is above all by the excellence of his nature, yet in all as cause of their being. Spiritual things contain what they are in, as the soul contains the body; so God is in things as containing them."},
  rubric:["Objection argues from transcendence or containment.","Sed contra argues from God's operation in all things.","Respondeo: agent present to its effect; created being his proper effect.","Respondeo: caused continually (sun and air) and innermost.","Reply distinguishes being 'above' from being 'in', and spiritual containing."]},
 drill:{title:"Order the steps of q.8 a.1",parts:["An agent must be joined to what it acts on","Created being is God's proper effect","He causes it as long as things exist, as the sun lights the air","Being is innermost in each thing","So God is in all things, and innermostly"]},
 connections:`<p><strong>Back.</strong> F4's limitation of act by potency gives infinity; L2's simplicity (q.3 a.8) separates omnipresence from pantheism; T5's conservation and T4's missions are the two modes of presence.</p><p><strong>Forward.</strong> L5 adds that this present God is also unchanging and eternal, present to all times as to all places. T9a (prayer) and T13 (the Real Presence of Christ in the Eucharist, a third, sacramental mode) build on it.</p><p><strong>Psychology.</strong> See section 5 on mindfulness and recollection; P8 develops attention and emotion regulation.</p>`},

// ===================== L5 IMMUTABILITY, ETERNITY, UNITY =====================
{id:"t3l5",ord:5,code:"T3 · Lesson 5",title:"Immutable, eternal and one (ST I qq.9–11)",
 outcomes:["Give Thomas's three arguments that God is altogether immutable and interpret Scripture's language of divine change (q.9).","Explain Boethius's definition of eternity, phrase by phrase, and why eternity follows immutability (q.10 aa.1–2).","Distinguish eternity, aeviternity and time (q.10 aa.4–5).","Explain what 'one' adds to 'being' and give the three arguments that God is one (q.11).","Show how divine unity and simplicity are compatible with the Trinity, recalling T4."],
 prereq:["immutability","eternity","aeviternity","one-trans","actus-purus","simplicity","relation-divine"],
 recall:[
  ["t3l4","Why is God infinite?","Because his being is not received in any essence that would limit it: he is his own subsistent being (q.7 a.1)."],
  ["f3","How is motion (change) defined?","The reduction of something from potency to act. Whatever changes was in potency to what it becomes."],
  ["t3l2","What kinds of composition does q.3 exclude from God?","Quantitative parts, matter and form, nature and suppositum, essence and existence, genus and difference, subject and accident."],
  ["t4","Where does real distinction in God come from?","Only from relative opposition: paternity and filiation, active and passive spiration. 'In God all is one where there is no opposition of relation' (Florence; CCC 255)."]],
 reading:{primary:[["ST I q.9 aa.1–2 (immutability)",NA("1009.htm")],["ST I q.10 aa.1–6 (eternity)",NA("1010.htm")],["ST I q.11 aa.1–4 (unity)",NA("1011.htm")],["Boethius, Consolation of Philosophy V, prose 6",'https://www.gutenberg.org/ebooks/14328'],["CCC 200–202, 212",'https://www.vatican.va/archive/ENG0015/__P17.HTM']],
  secondary:["Stump, E. and Kretzmann, N. (1981) 'Eternity', The Journal of Philosophy, 78(8), pp. 429–458. doi:10.2307/2026047.","Dodds, M.J. (2008) The Unchanging God of Love: Thomas Aquinas and Contemporary Theology on Divine Immutability. 2nd edn. Washington, DC: CUA Press.","Weinandy, T.G. (2000) Does God Suffer? Edinburgh: T&T Clark.","Leftow, B. (1991) Time and Eternity. Ithaca: Cornell University Press."]},
 scripture:[["Malachi 3:6, I am the Lord, and I change not",null],["James 1:17, no change nor shadow of alteration",null],["Psalm 101 (102):26–28, thou art always the selfsame",null],["Deuteronomy 6:4, the Lord our God is one Lord",null]],
 sections:[
 {id:"s1",h:"1. God is altogether immutable (q.9 a.1)",html:`<p>The sed contra is Scripture: \"I am the Lord, and I change not\" (Mal 3:6). The respondeo gives three arguments, each drawn from an earlier question:</p>
<ol><li><strong>From pure act (q.2, q.3).</strong> Whatever changes is in some way in potency. God is pure act. So he cannot change in any way.</li>
<li><strong>From simplicity (q.3).</strong> Whatever changes remains partly the same and partly passes away, so it is composite. God is altogether simple.</li>
<li><strong>From infinity (q.7).</strong> Whatever changes acquires something by its change, something it did not have before. God, infinite and containing all perfection, can acquire nothing.</li></ol>
${RC("t3l2",`<p>Notice the method. No new principle is introduced: immutability follows from <strong>pure act</strong> (the First Way), <strong>simplicity</strong> (L2) and <strong>infinity</strong> (L4). Each attribute is the same simple being seen from another side.</p>`)}
<p><strong>Article 2.</strong> God alone is altogether immutable. Every creature is mutable at least in this: it could not have existed, and could cease to exist if God withheld being.</p>`,
  check:Q("Which earlier conclusion grounds the third argument for immutability?",[["Simplicity","That grounds the second."],["Infinity: God can acquire nothing","Correct."],["Omnipresence","Not used here."]],1)},
 {id:"s2",h:"2. When Scripture says God 'repents' or 'draws near'",html:`<p>Scripture says: \"It repented him that he had made man on the earth\" (Gen 6:6) and \"Draw nigh to God: and he will draw nigh to you\" (Jas 4:8). Thomas answers the second directly:</p>
<div class="quote">"These things are said of God in Scripture metaphorically. For as the sun is said to enter a house, or to go out, according as its rays reach the house, so God is said to approach to us, or to recede from us, when we receive the influx of His goodness, or decline from Him."<span class="src">ST I q.9 a.1 ad 3 · Dominican tr. (1920)</span></div>
${RC("f6",`<p>This is the rule for <strong>metaphorical names</strong> from F6: a name that includes a bodily or changing mode in its meaning is said of God by likeness of effect. God "repents" when he does what a repentant man would do: he changes the work, not his will. Thomas says it directly in q.19 a.7: \"to change the will is one thing; to will that certain things should be changed is another.\"</p>`)}
<div class="co bridge"><div class="co-h">A live debate: does an immutable God love?</div><p>Process theology and some modern theologians (Moltmann, 1974) argue that a God who cannot change or suffer cannot truly love or respond. Thomists answer that God's love is not less but more than responsive: it is not caused by its object but causes all the goodness in it (q.20 a.2, Lesson 8). God does not need to become compassionate; he is compassion in act. In Christ the Son truly suffers, <em>in his human nature</em> (T11). See Dodds (2008) and Weinandy (2000). <span class="voice">Magisterium</span>The Church confesses God \"immutable\" (Lateran IV, DS 800; Vatican I, Dei Filius ch. 1, DS 3001).</p></div>`,
  check:Q("How does Thomas interpret 'Draw nigh to God and he will draw nigh to you'?",[["God literally moves toward us","God is not a body."],["Metaphorically: we receive or turn from his goodness, as a house receives or loses the sun's rays","Correct: q.9 a.1 ad 3."],["As proof that God changes","No."]],1)},
 {id:"s3",h:"3. Eternity: Boethius's definition (q.10 aa.1–3)",html:`<p>Boethius defined eternity as \"the simultaneously-whole and perfect possession of interminable life\" (<em>interminabilis vitae tota simul et perfecta possessio</em>). Thomas defends each phrase:</p>
<div class="anatomy">
 <div class="part"><div class="label">Interminable</div><div>No beginning and no end: no term on either side.</div></div>
 <div class="part"><div class="label">Life</div><div>Eternity measures not bare existence but the life of one who acts from within; God's being is his life (ad 2).</div></div>
 <div class="part"><div class="label">Simultaneously-whole</div><div>No succession, no before and after. This is the essential mark that distinguishes eternity from time.</div></div>
 <div class="part"><div class="label">Perfect possession</div><div>Nothing is lacking or still to be gained; held firmly and quietly.</div></div></div>
<p><strong>How we reach it.</strong> We know simple things through composite ones, so we know eternity through time. Time is \"the numbering of movement by 'before' and 'after'\". Where there is no movement there is no before and after, and so the measure is not time but eternity (a.1). So: \"The idea of eternity follows immutability, as the idea of time follows movement\" (a.2).</p>
<p>And because God is his own being, he is not only eternal: \"He is His own eternity\" (a.2). Eternity truly so called belongs to God alone (a.3).</p>
${RC("t3l2",`<p>Compare q.3: God does not <em>have</em> wisdom, he <em>is</em> his wisdom. Likewise he does not <em>have</em> a duration called eternity; he <em>is</em> it. The same simplicity, the same pattern of speech.</p>`)}
<div class="co warn"><div class="co-h">Common misunderstanding</div><p>Eternity is not endless time (sempiternity). Thomas holds that even a world with no beginning and no end would still be in time, because it would have succession. The essential difference is "simultaneously-whole", not "without end" (a.4).</p></div>`,
  check:Q("What, for Thomas, is the essential difference between eternity and time?",[["Eternity has no beginning or end","He says this is accidental (a.4)."],["Eternity is simultaneously whole, without before and after","Correct."],["Time is measured by clocks","Not the point."]],1)},
 {id:"s4",h:"4. Time, aeviternity, eternity (q.10 aa.4–6)",html:`<p>Thomas distinguishes three measures of duration:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Measure</th><th>Of what</th><th>Being</th><th>Operations</th></tr></thead><tbody>
<tr><td><strong>Time</strong></td><td>Bodily, changing things</td><td>Changeable (generated and corrupted)</td><td>Successive</td></tr>
<tr><td><strong>Aeviternity</strong> (aevum)</td><td>Angels; the heavenly bodies (in his cosmology); the blessed</td><td>Unchangeable</td><td>Can be successive (thoughts, choices)</td></tr>
<tr><td><strong>Eternity</strong></td><td>God alone</td><td>Unchangeable</td><td>No succession at all</td></tr></tbody></table></div>
<p>Aeviternity is \"the mean between\" time and eternity (a.5).</p>
${RC("t5",`<p>From T5: an angel has no matter, so nothing in its being wears out or corrupts. Yet it thinks and chooses, and the bad angels' one free choice was an act that happened. Aeviternity names this: unchanging being, changeable acts.</p>`)}
<div class="co core"><div class="co-h">Preview · eternity and the future</div><p>Because God's 'now' is not a moment within time, all of time is present to it at once. This will be the key to how God knows future contingent events without making them necessary (q.14 a.13, Lesson 7). Thomas's image: one who stands on a height sees at once all who pass along a road, while each traveller sees only those beside him.</p></div>`,
  check:Q("Aeviternity differs from eternity because in aeviternal beings…",[["being changes","No: their being is unchangeable."],["operations can be successive","Correct: q.10 a.5."],["there is no beginning","God's eternity has none either; that is not the difference."]],1)},
 {id:"s5",h:"5. God is one (q.11)",html:`<p><strong>What 'one' means (a.1).</strong> \"'One' does not add any reality to 'being'; but is only a negation of division; for 'one' means undivided 'being.'\" This transcendental one differs from the one that begins counting.</p>
${RC("t3l3",`<p>One is the second <strong>transcendental</strong> in this treatise. In L3 good added to being a relation to appetite. One adds only a negation: undivided.</p>`)}
<p><strong>Three arguments that God is one (a.3):</strong></p>
<ol><li><strong>From simplicity.</strong> What makes a thing 'this' cannot be shared. Socrates' humanity is shared by many men, but what makes him <em>this</em> man belongs to him alone. In God, his nature is identical with himself (q.3 a.3). So what makes him God makes him this God, and there cannot be many.</li>
<li><strong>From infinite perfection.</strong> If there were many gods they would differ; so one would have something the other lacked, and that one would not be all-perfect.</li>
<li><strong>From the unity of the world.</strong> All things are found ordered to one another. Diverse things are not brought into one order except by one: \"one is the per se cause of one, and many are only the accidental cause of one\".</li></ol>
<p><strong>Supremely one (a.4).</strong> God is supremely being and supremely undivided, divided \"neither actually nor potentially\". \"Hear, O Israel, the Lord our God is one Lord\" (Deut 6:4).</p>
${RC("t4",`<p>How is this compatible with three persons? T4 gave the answer. The unity of q.11 is unity of <strong>essence</strong>. The persons are distinguished only by <strong>opposed relations</strong>, which are really identical with the one essence (q.28 a.2). So Thomas treats the one God first (qq.2–26), then the three persons (qq.27–43), without contradiction: three subsisting relations, one undivided being.</p>`)}`,
  check:Q("Thomas's first argument in q.11 a.3 that God is one rests on…",[["the unity of the world","That is the third."],["simplicity: what makes God God is what makes him this God","Correct."],["Deuteronomy 6:4","Scripture is the sed contra, not the argument."]],1)}
 ],
 quiz:[
  Q("Which of these is NOT one of the three arguments of q.9 a.1?",[["From pure act","It is."],["From simplicity","It is."],["From infinity","It is."],["From the Trinity","Correct: q.9 is about the one God, before the Trinity."]],3,"ST I q.9 a.1",{bloom:"Understand",terms:["immutability"],diff:2}),
  Q("Why is every creature at least in some way mutable (q.9 a.2)?",[["Because every creature is a body","Angels are not bodies."],["Because its being depends on God and could cease if he withheld it","Correct."],["Because creatures sin","Not all creatures sin."],["Because creatures are in a place","Not the reason given."]],1,"ST I q.9 a.2",{bloom:"Understand",terms:["immutability"],diff:2}),
  Q("When Scripture says God 'repented', Thomas reads this as…",[["a literal change in God's will","No."],["metaphor: God changes his work, not his will","Correct: q.9 a.1 ad 3; q.19 a.7."],["an error","No."],["a sign of two gods","No."]],1,"ST I q.19 a.7",{bloom:"Apply",terms:["immutability"],diff:2}),
  Q("Boethius's definition of eternity is…",[["endless duration","That is sempiternity."],["the simultaneously-whole and perfect possession of interminable life","Correct."],["the sum of all times","No."],["time without change","No."]],1,"ST I q.10 a.1",{bloom:"Remember",terms:["eternity"],diff:1}),
  Q("Time, according to q.10 a.1, is…",[["the numbering of movement by before and after","Correct."],["eternity divided","No."],["an illusion","No."],["the life of God","No."]],0,"ST I q.10 a.1",{bloom:"Remember",terms:[],diff:1}),
  Q("Eternity follows immutability as…",[["time follows movement","Correct: q.10 a.2."],["cause follows effect","Reversed."],["life follows death","No."],["one follows many","No."]],0,"ST I q.10 a.2",{bloom:"Understand",terms:["eternity"],diff:2}),
  Q("The measure of an angel's duration is…",[["time","No."],["aeviternity","Correct: q.10 a.5."],["eternity","Only God's."],["none","No."]],1,"ST I q.10 a.5",{bloom:"Remember",terms:["aeviternity"],diff:1}),
  Q("'One', as a transcendental, adds to being…",[["a number","That is quantitative one."],["only the negation of division","Correct: q.11 a.1."],["a real accident","No."],["a relation to appetite","That is good."]],1,"ST I q.11 a.1",{bloom:"Understand",terms:["one-trans"],diff:2}),
  Q("The argument 'many are only the accidental cause of one' belongs to which proof of God's unity?",[["From simplicity","No."],["From infinite perfection","No."],["From the unity of the world's order","Correct: q.11 a.3."],["From Scripture","No."]],2,"ST I q.11 a.3",{bloom:"Analyse",terms:[],diff:3}),
  Q("The unity of God in q.11 is compatible with three persons because…",[["the persons are parts of God","God has no parts."],["it is unity of essence, and the persons are distinguished only by opposed relations identical with that essence","Correct: q.28 aa.2–3 (T4)."],["the persons are three gods","Tritheism."],["the persons are only names","Modalism."]],1,"ST I q.11; q.28",{bloom:"Evaluate",terms:["relation-divine"],diff:3})
 ],
 construct:{q:"Whether God is altogether immutable?",ref:"ST I q.9 a.1",
  model:{obj:"It seems not: whatever moves itself is in some way mutable, and Augustine says the Creator Spirit moves himself; further, Scripture says, \"Draw nigh to God and He will draw nigh to you\" (Jas 4:8).",sc:"\"I am the Lord, and I change not\" (Mal 3:6).",resp:"God is altogether immutable. First, he is pure act, and whatever changes is in potency. Second, whatever changes is composite, and God is simple. Third, whatever changes acquires something, and God, infinite, contains all perfection.",rep:"Augustine speaks of 'movement' in the wide sense in which understanding and willing are called movements. Scriptural nearness and distance are metaphors: as the sun 'enters' a house when its rays reach it, so God approaches when we receive his goodness."},
  rubric:["Objection gives a real authority or Scripture text.","Sed contra quotes Malachi 3:6.","Respondeo gives all three arguments (act, simplicity, infinity).","Each argument names its earlier source (q.2–3, q.3, q.7).","Reply interprets the change-language as metaphor."]},
 drill:{title:"Put De Deo Uno qq.3–11 in Thomas's order",parts:["Simplicity (q.3)","Perfection (q.4)","Goodness (qq.5–6)","Infinity (q.7)","Omnipresence (q.8)","Immutability (q.9)","Eternity (q.10)","Unity (q.11)"]},
 connections:`<p><strong>Back.</strong> Every argument in this lesson reuses earlier ones: pure act (L1), simplicity (L2), perfection and the transcendentals (L3), infinity (L4). The answer about the Trinity reuses T4.</p><p><strong>Forward.</strong> With q.11, Thomas closes the treatment of God's being. Lesson 6 asks how we can know and name such a God (qq.12–13). Lessons 7–10 treat his operations: knowledge, will, providence, power. Eternity is the key to foreknowledge (L7) and predestination (L9).</p><p><strong>Psychology.</strong> Human beings experience time as succession, and anxiety is largely future-directed (Barlow, 2002). The Christian tradition speaks of the 'sacrament of the present moment' (de Caussade): the present is where time touches eternity. This is a spiritual reading, not a clinical technique, but it fits well with present-focused CBT work (P4).</p>`}
]);

Object.assign(EXTRAS,{
 t3l2:{plain:{version:"Having shown that God exists, Thomas asks what he is like. Since we only know God from creatures, we proceed by removing from him everything that belongs to creatures as creatures, starting with every kind of part or composition.",question:"Is God made of anything, or put together from anything?",one:"God has no parts of any kind: he is not a body, he is his own nature, and his nature is simply to be."},
  hook:"\"B-M-N-E-G-A\": Body, Matter, Nature/suppositum, Essence/existence, Genus, Accidents: six compositions denied, then 'altogether simple'.",
  analogy:{title:"The white light and the prism",text:"White light is one, yet a prism splits it into many colours. God's being is one; creatures, like a prism, show it to us as many perfections: wisdom, power, goodness. The many names are true, but what they name in God is one."},
  sort:{title:"Which composition does each example illustrate?",cats:["Matter and form","Essence and existence","Substance and accident","Genus and difference"],items:[["A statue: bronze shaped as a horse",0],["A phoenix can be understood without knowing whether one exists",1],["Socrates becoming pale",2],["Man as 'rational animal'",3],["A dog's body and its animating principle",0],["Solomon's wisdom, which he could lose",2]]}},
 t3l3:{plain:{version:"If God is the first cause of everything, everything good in the world must already be in him, but in a higher way. Every being, just by being, is good; God alone is goodness itself.",question:"Is everything good in creatures found in God, and what makes anything good at all?",one:"Being and good are the same reality; God is good by essence, creatures by a real but received likeness of his goodness."},
  hook:"\"Desire → perfect → actual → exists\": the four steps that make being and good convertible (q.5 a.1).",
  analogy:{title:"Sunlight in coloured glass",text:"Each window of a cathedral glows with its own colour, really its own; yet without the sun it would be dark. Creatures are good with their own goodness, and all of it is light from God."},
  sort:{title:"Sort each good into its kind (q.5 a.6)",cats:["Honest (virtuous)","Useful","Pleasant"],items:[["Friendship with God",0],["Money",1],["The enjoyment of a good meal",2],["A medicine",1],["Justice",0],["Rest after work",2]]}},
 t3l4:{plain:{version:"God is unlimited, because his being is not poured into any container that would limit it. And because he is always giving being to everything, he is present in everything, more inwardly than anything else.",question:"Is God limited, and where is he?",one:"God is in all things as the cause of their being, which is innermost in them; in the just he is also present as known and loved."},
  hook:"\"E-P-P\": Essence (cause of being), Presence (all things open to his eyes), Power (all subject to him).",
  analogy:{title:"The sun and the lit air",text:"Air is lit only while the sun shines on it; take the sun away and the light is gone at once. Creatures have being in the same way: not like a house that stands after the builder leaves, but like air that is lit as long as the sun gives light."},
  sort:{title:"Which picture of God does each statement express?",cats:["Thomist","Deist","Pantheist"],items:[["God made the world and now leaves it to run",1],["God is the soul of the world",2],["God is in all things as the cause of their being",0],["Everything is a part of God",2],["The world would continue if God withdrew",1],["God is innermost in each thing but not part of it",0]]}},
 t3l5:{plain:{version:"Because God is perfectly actual, he cannot change; because he cannot change, he does not live in time but possesses his whole life at once; and because he is simple and infinite, there can only be one God.",question:"Does God change, does he live in time, and could there be more than one God?",one:"God is unchanging, eternal (all at once, not endless) and one; his unity is of essence, compatible with three persons."},
  hook:"\"Act, Simple, Infinite\" give immutability; \"Interminable, Life, Whole, Perfect\" define eternity.",
  analogy:{title:"The watcher on the hill",text:"Travellers on a winding road see only those near them. One standing on a high hill sees the whole road at once. Eternity is like the hill: all of time is present to it, without the hill moving along the road."},
  sort:{title:"Match each being to its measure of duration",cats:["Time","Aeviternity","Eternity"],items:[["A human body",0],["The archangel Michael",1],["God",2],["A mountain",0],["A saint in glory (as to the soul's unchanging state)",1],["The Trinity",2]]}}
});
